/* Supplied CKL anniversary question bank. Source: Spin the wheel content PDF. */
window.CKL_CATEGORIES=['Where it all began','Coming home to Kenya','CKL surprises','Made Kenyan','Made in Kenya','Brands farmers trust','Growing together','Caring for the land'];
